module pwm_divider(
	clk,
	reset,
	duty,
	pwm);

	//---Ports declearation: generated by Robei---
	input clk;
	input reset;
	input [19:0] duty;
	output pwm;

	wire clk;
	wire reset;
	wire [19:0] duty;
	reg pwm;

	//----Code starts here: integrated by Robei-----
	 reg [19:0] count;
	
	always @ (posedge clk or negedge reset)begin
	if(reset==0)
	   count<=0;
	else if(count<20'd1_000_000)//占空比设置
	   count<=count+1;
	else
	   count<=0;
	   end
	
	
	always @ (clk or duty)begin
	if(count<duty)//输出高低电平
	    pwm<=1;
	else
	   pwm<=0;
	 end
	
	
	
endmodule    //pwm_divider

